public bool CheckCarrierBeforeLoaderMove()
        {
            // 出料、入料口是否有载具
            bool hasMaterialInOutlet = false;
            bool hasMaterialInFeedinglet = false;

        Retry:
            // 出料口检测
            hasMaterialInOutlet =
                this.UnloadingSubSectionController.HasMaterialInFeedingInlet();

            if (MachineHardwareConfiguration.GetInstance().LoadConfiguration == LoadConfigurationEnum.LoaderBin
                || MachineHardwareConfiguration.GetInstance().LoadConfiguration
                == LoadConfigurationEnum.OnlineWithAutoUnloader)
            {
                if (hasMaterialInOutlet)
                {
                    DialogResult dr = AKRSMessageBoxExt.Show(
                        @"出料口有载具，下料仓不允许移动!请先移除出料口的载具！
                              点击
                              重试 : 重新检测
                              终止: 停止工作",
                        $"提示",
                        new[] { "重试", "终止" },
                        new[] { DialogResult.Retry, DialogResult.Abort },
                        AlarmLevel.SecondLevel);

                    switch (dr)
                    {
                        case DialogResult.Retry:
                            goto Retry;

                        case DialogResult.Abort:
                            // 停止
                            return false;
                    }
                }
            }

            // 入料口检测
            hasMaterialInFeedinglet =
                this.DispenseSubSectionController.HasMaterialInFeedingInlet();

            if (MachineHardwareConfiguration.GetInstance().LoadConfiguration == LoadConfigurationEnum.LoaderBin
                || MachineHardwareConfiguration.GetInstance().LoadConfiguration
                == LoadConfigurationEnum.OnlineWithAutoLoader)
            {
                if (hasMaterialInFeedinglet)
                {
                    DialogResult dr = AKRSMessageBoxExt.Show(
                        @"入料口有载具，上料仓不允许移动!请先移除入料口的载具！
                              点击
                              重试 : 重新检测
                              终止: 停止工作",
                        $"提示",
                        new[] { "重试", "终止" },
                        new[] { DialogResult.Retry, DialogResult.Abort },
                        AlarmLevel.SecondLevel);

                    switch (dr)
                    {
                        case DialogResult.Retry:
                            goto Retry;

                        case DialogResult.Abort:
                            // 停止
                            return false;
                    }
                }
            }

            return true;
        }

public void MapMaterial()
        {
            // 1. 倒转检测 点胶和 Bond载台上是有有料, 并判断在是否和载台记忆是否符合，不符合则报警
            this.BondSubSectionController.MapBelt(true);
            if (MachineHardwareConfiguration.GetInstance().IsSystem1Configrated)
            {
                this.DispenseSubSectionController.MapBelt(true);
            }

            if (MachineHardwareConfiguration.GetInstance().LoadConfiguration == LoadConfigurationEnum.Online || MachineHardwareConfiguration.GetInstance().LoadConfiguration == LoadConfigurationEnum.OnlineWithAutoLoader)
            {
                this.transportProgram.LoadingSubSectionProgram.SubSectionState = this.LoadingSubSectionController.HasMaterialOnFront() ? SubSectionStateEnum.HasMaterial : SubSectionStateEnum.NoMaterial;
            }
        }

public override void MapBelt(bool autoWork)
        {
            if (MachineHardwareConfiguration.GetInstance().IsTransportConfigured)
            {
                // 只有当流道不反找且是自动工作且轨道上有料的时候才不反照
                if (!TransportDevicePara.GetInstance().IsReverseSearch
                    && autoWork
                    && this.bondSubSectionProgram.TransportUnit != null)
                {
                    return;
                }

                bool hasMaterial = this.SearchBelt();

                // 如果检测到有料
                if (hasMaterial)
                {
                    // 当缓存中没有料 
                    if (this.bondSubSectionProgram.TransportUnit == null)
                    {
                        DialogResult dr = AKRSMessageBoxExt.ShowWarn(
                            @" 设备记忆中系统2没有载具，此次搜索发现了载具，请确认是否真的存在载具。
                              有:  有载具, 设备将记录此载具
                              没有: 没有载具",
                            $"警告",
                            new[] { "有", "没有" },
                            new[] { DialogResult.Yes, DialogResult.No });

                        switch (dr)
                        {
                            case DialogResult.Yes:

                                this.bondSubSectionProgram.TransportUnit =
                                    new TransportUnit(CurrentMachineSystemEnum.System2);

                                this.bondSubSectionProgram.SubSectionState = SubSectionStateEnum.HasMaterial;

                                break;

                            case DialogResult.No:
                                this.bondSubSectionProgram.SubSectionState = SubSectionStateEnum.NoMaterial;
                                break;
                        }
                    }
                    else   // 如果缓存中有料
                    {
                        this.bondSubSectionProgram.SubSectionState = SubSectionStateEnum.HasMaterial;
                        this.bondSubSectionProgram.TransportUnit.Refresh();
                    }
                }
                else   // 没有搜索到料
                {
                    if (this.bondSubSectionProgram.TransportUnit != null)
                    {
                        DialogResult dr = AKRSMessageBoxExt.ShowWarn(
                            @" 设备记忆中系统2有载具，此次收索没有发现载具，请确认是否真的存在载具。
                              有:  有载具
                              没有: 没有载具, 设备将清空此载具记忆",
                            $"警告",
                            new[] { "有", "没有" },
                            new[] { DialogResult.Yes, DialogResult.No });

                        switch (dr)
                        {
                            case DialogResult.Yes:
                                this.bondSubSectionProgram.SubSectionState = SubSectionStateEnum.HasMaterial;

                                break;

                            case DialogResult.No:
                                this.bondSubSectionProgram.TransportUnit = null;
                                this.bondSubSectionProgram.SubSectionState = SubSectionStateEnum.NoMaterial;
                                break;
                        }
                    }
                    else   // 如果没料
                    {
                        this.bondSubSectionProgram.TransportUnit = null;
                        this.bondSubSectionProgram.SubSectionState = SubSectionStateEnum.NoMaterial;
                    }
                }
            }
            else
            {
                // 只有当流道不反找且是自动工作且轨道上有料的时候才不反照
                if (!TransportDevicePara.GetInstance().IsReverseSearch
                    && autoWork
                    && this.bondSubSectionProgram.TransportUnit != null)
                {
                    return;
                }

            RetryCommand:

                bool isSuccess = this.OpenVacuumAndCheck();

                if (isSuccess)
                {
                    if (this.bondSubSectionProgram.TransportUnit == null)
                    {
                        DialogResult dr = AKRSMessageBoxExt.ShowWarn(
                            @" 设备记忆中系统2没有载具，此次搜索发现了载具，请确认是否真的存在载具。
                              有:  有载具, 设备将记录此载具
                              没有: 没有载具",
                            $"警告",
                            new[] { "有", "没有" },
                            new[] { DialogResult.Yes, DialogResult.No });

                        switch (dr)
                        {
                            case DialogResult.Yes:

                                this.bondSubSectionProgram.TransportUnit =
                                    new TransportUnit(CurrentMachineSystemEnum.System2);

                                this.bondSubSectionProgram.SubSectionState = SubSectionStateEnum.HasMaterial;

                                break;

                            case DialogResult.No:
                                this.bondSubSectionProgram.SubSectionState = SubSectionStateEnum.NoMaterial;
                                break;
                        }
                    }
                    else
                    {
                        this.bondSubSectionProgram.SubSectionState = SubSectionStateEnum.HasMaterial;
                    }
                }
                else
                {
                    if (this.bondSubSectionProgram.TransportUnit != null)
                    {
                        DialogResult dr = AKRSMessageBoxExt.ShowWarn(
                            @" 设备记忆中系统2有载具，此次收索没有发现载具，请确认是否真的存在载具。
                              有:  有载具
                              没有: 没有载具, 设备将清空此载具记忆",
                            $"警告",
                            new[] { "有", "没有" },
                            new[] { DialogResult.Yes, DialogResult.No });

                        switch (dr)
                        {
                            case DialogResult.Yes:
                                this.bondSubSectionProgram.SubSectionState = SubSectionStateEnum.HasMaterial;

                                break;

                            case DialogResult.No:
                                this.bondSubSectionProgram.TransportUnit = null;
                                this.bondSubSectionProgram.SubSectionState = SubSectionStateEnum.NoMaterial;
                                break;
                        }
                    }
                    else
                    {
                        DialogResult dr = AKRSMessageBoxExt.ShowWarn(
                            @" 未工作台上未发现产品，请确证产品是否存在漏真空",
                            $"警告",
                            new[] { "重试", "退出" },
                            new[] { DialogResult.Retry, DialogResult.No });

                        switch (dr)
                        {
                            case DialogResult.Retry:
                                goto RetryCommand;

                            case DialogResult.No:
                                this.bondSubSectionProgram.TransportUnit = null;
                                this.bondSubSectionProgram.SubSectionState = SubSectionStateEnum.NoMaterial;
                                this.CloseVacuum();
                                break;
                        }
                    }
                }
            }
        }

public override bool SearchBelt()
        {
            if (MachineHardwareConfiguration.GetInstance().IsTransportConfigured)
            {
                retry:
                // bond夹爪归位，bond气缸升起
                this.UnClamp();

                // 点胶载台皮带先进行倒转
                double transportDistance =
                    this.bondSubSectionProgram.TransportBeltSetting.BackwardTransportDistance;

                this.bondSubSectionModule.SendRelativeMoveCommandBelt(
                    -transportDistance,
                    this.bondSubSectionProgram.TransportBeltSetting.BackwardVelRate);

                // 入料感应器是否感应到料
                bool isSensorTrigger = false;

                // 检测传感器 判断状态
                while (this.bondSubSectionModule.IsMoving())
                {
                    // 如果点胶出料口有料
                    if (this.dispenseSubSectionModule.HasMaterialInOutlet())
                    {
                        isSensorTrigger = true;

                        // 停止倒转
                        this.StopMove();
                        this.dispenseSubSectionModule.StopMove();

                        Thread.Sleep(100);
                        break;
                    }
                }

                // 如果没感应到
                if (isSensorTrigger == false)
                {
                    return false;
                }

                Thread.Sleep(50);

                // Bond挡料气缸1顶起
                this.BlockCylinderUpAndDelay(50);

                // 检测到了 正转
                this.bondSubSectionModule.RelativeMoveBelt(
                    this.bondSubSectionProgram.TransportBeltSetting.ForwardTransportDistance,
                    this.bondSubSectionProgram.TransportBeltSetting.ForwardVelRate);

                // 此时如果点胶出料口有料 则是卡料 报警
                if (this.dispenseSubSectionModule.HasMaterialInOutlet())
                {
                    // 报警：入料卡料
                    DialogResult dr = AKRSMessageBoxExt.Show(
                        @"固晶工作台卡料，请选择如何处理
                              点击
                              重试 : 重新搜索
                              忽略 : 忽略",
                        $"报警",
                        new[] { "重试", "忽略" },
                        new[] { DialogResult.Retry, DialogResult.Ignore });

                    switch (dr)
                    {
                        case DialogResult.Retry:
                            goto retry;

                        case DialogResult.Ignore:
                            return false;
                    }
                }

                // 传输成功,夹紧夹爪
                this.Clamp();

                return true;
            }
            else
            {
                try
                {
                    this.OpenVacuumAndCheck();
                    return true;
                }
                catch (Exception e)
                {
                    return false;
                }
            }
        }

public override void MapBelt(bool AutoWork)
        {
            // 只有当流道不反找且是自动工作且轨道上有料的时候才不反照
            if (!TransportDevicePara.GetInstance().IsReverseSearch
                && AutoWork
                && this.dispenseSubSectionProgram.TransportUnit != null)
            {
                return;
            }

            bool hasMaterial = this.SearchBelt();

            // 如果检测到有料
            if (hasMaterial) 
            {
                // 当缓存中没有料 
                if (this.dispenseSubSectionProgram.TransportUnit == null)
                {
                    DialogResult dr = AKRSMessageBoxExt.ShowWarn(
                        @" 设备记忆中系统1没有载具，此次搜索发现了载具，请确认是否真的存在载具。
                              Yes:  有载具, 设备将记录此载具
                              No: 没有载具",
                        $"警告",
                        new[] { "Yes", "No" },
                        new[] { DialogResult.Yes, DialogResult.No });

                    switch (dr)
                    {
                        case DialogResult.Yes:

                            this.dispenseSubSectionProgram.TransportUnit =
                                new TransportUnit(CurrentMachineSystemEnum.System1);

                            this.dispenseSubSectionProgram.SubSectionState = SubSectionStateEnum.HasMaterial;

                            break;

                        case DialogResult.No:
                            this.dispenseSubSectionProgram.SubSectionState = SubSectionStateEnum.NoMaterial;
                            break;
                    }
                }
                else   // 如果有料
                {
                    this.dispenseSubSectionProgram.SubSectionState = SubSectionStateEnum.HasMaterial;
                    this.dispenseSubSectionProgram.TransportUnit.Refresh();
                }
            }
            else   // 没有搜索到料
            {
                if (this.dispenseSubSectionProgram.TransportUnit != null)
                {
                    DialogResult dr = AKRSMessageBoxExt.ShowWarn(
                        @" 设备记忆中系统1有载具，此次收索没有发现载具，请确认是否真的存在载具。
                              有:  有载具
                              没有: 没有载具, 设备将清空此载具记忆",
                        $"警告",
                        new[] { "有", "没有" },
                        new[] { DialogResult.Yes, DialogResult.No });

                    switch (dr)
                    {
                        case DialogResult.Yes:
                            this.dispenseSubSectionProgram.SubSectionState = SubSectionStateEnum.HasMaterial;

                            if (!this.dispenseSubSectionProgram.IsTuInDispense1)
                            {
                                this.dispenseSubSectionProgram.TransportUnit.System1BackMoveDistance();
                            }

                            break;

                        case DialogResult.No:
                            this.dispenseSubSectionProgram.TransportUnit = null;
                            this.dispenseSubSectionProgram.SubSectionState = SubSectionStateEnum.NoMaterial;
                            break;
                    }
                }
                else   // 如果没料
                {
                    this.dispenseSubSectionProgram.TransportUnit = null;
                    this.dispenseSubSectionProgram.SubSectionState = SubSectionStateEnum.NoMaterial;
                }
            }

            this.dispenseSubSectionProgram.IsTuInDispense1 = true;
        }

public override bool SearchBelt()
        {
        retry:

            if (MachineHardwareConfiguration.GetInstance().IsSystem1Configrated)
            {
                // 点胶夹爪归位，点胶气缸升起
                this.UnClamp();
            } 

            // 搜索到有料之后在打开挡料气缸，提前升起就会卡料，针对于点胶1和点胶2
            //// 点胶挡料气缸1顶起
            this.BlockCylinder1DownAndDelay(50);

            // 点胶载台皮带先进行倒转
            double transportDistance =
                this.dispenseSubSectionProgram.TransportBeltSetting.BackwardTransportDistance;

            this.dispenseSubSectionModule.SendRelativeMoveCommandBelt(
               -transportDistance,
                this.dispenseSubSectionProgram.TransportBeltSetting.BackwardVelRate);

            // 入料感应器是否感应到料
            bool isSensorTrigger = false;

            // 检测传感器 判断状态
            while (this.dispenseSubSectionModule.IsMoving())
            {
                if (this.dispenseSubSectionModule.HasMaterialInFeedingInlet())
                {
                    isSensorTrigger = true;

                    // 停止倒转
                    this.dispenseSubSectionModule.StopMove();
                    Thread.Sleep(20);
                    break;
                }
            }

            // 如果没感应到
            if (isSensorTrigger == false)
            {
                return false;
            }

            //double distance = TransportProgram.GetInstance().DispenseSubSectionProgram.BondinsertSetting
            //    .HardstopRightDistance;

            // 点胶挡料气缸1、2顶起
            this.BlockCylinder1UpAndDelay(50);
            this.BlockCylinder2UpAndDelay(50);

            // 检测到了 正转
            this.dispenseSubSectionModule.RelativeMoveBelt(
                this.dispenseSubSectionProgram.TransportBeltSetting.ForwardTransportDistance,
                this.dispenseSubSectionProgram.TransportBeltSetting.ForwardVelRate);

            // 如果卡料 报警
            if (this.dispenseSubSectionModule.HasMaterialInFeedingInlet())
            {
                // 报警：入料卡料
                DialogResult dr = AKRSMessageBoxExt.Show(
                    @"点胶工作台卡料，请选择如何处理
                              点击
                              重试 : 重新搜索
                              忽略 : 忽略",
                    $"报警",
                    new[] { "重试", "忽略" },
                    new[] { DialogResult.Retry, DialogResult.Ignore });

                switch (dr)
                {
                    case DialogResult.Retry:
                        goto retry;

                    case DialogResult.Ignore:
                        return false;
                }
            }

            if (MachineHardwareConfiguration.GetInstance().IsSystem1Configrated)
            {
                // 传输成功,夹紧夹爪
                this.Clamp(true);
            }

            return true;
        }

public static void RecordTime(string item, string subItem)
        {
            LogHelper.Post(
                Level.Info,
                $"{System.DateTime.Now.ToString("MM-dd HH:mm:ss.fff")}: {item} - {subItem} 耗时：{TransportSystemStopwatch.ElapsedMilliseconds} ms",
                LogCategory.Transport,
                ViewType.InFileAndUI);

            TransportSystemStopwatch.Restart();
        }

public bool HasMaterialInFeedingInlet()
        {
            return this.unloadingSubSectionModule.HasMaterialInFeedingInlet();
        }

public bool HasMaterialInFeedingInlet()
        {
            return this.FeedMaterialCheckSensor.CheckStateForNums(true, 1, 200);
        }

public bool HasMaterialInFeedingInlet()
        {
            return this.dispenseSubSectionModule.HasMaterialInFeedingInlet();
        }

public bool HasMaterialInFeedingInlet()
        {
            return this.FeedMaterialCheckSensor.CheckStateForNums(true, 1, 0);
        }

public bool HasMaterialOnFront()
        {
            return this.loadingSubSectionModule.HasMaterialOnFront();
        }

public bool HasMaterialOnFront()
        {
            return this.MaterialExistFrontSensor.GetInputValue();
        }

public virtual void SendRelativeMoveCommandBelt(double transportDistance, double velRate)
        {
            this.BeltAxisX.SendRelativeMoveCommand(transportDistance, this.BeltAxisX.AxisMovePara.AbsoluteMoveSpeed * velRate);
        }

public virtual void RelativeMoveBelt(double transportDistance, double velRate)
        {
            this.BeltAxisX.RelativeMove(transportDistance, this.BeltAxisX.AxisMovePara.AbsoluteMoveSpeed * velRate);
        }

public virtual void StopMove()
        {
            if (this.BeltAxisX != null)
            {
                this.BeltAxisX.StopMove(false, true);
            }
           
        }

public virtual bool IsMoving()
        {
           return this.BeltAxisX.GetAxisState().Moving;
        }
